    int i;
    int j;
    int no;
};

struct cap{
    int no[1000];
    int ind;
    int fl;
};

cap caps[100][100];
vector<int>v[1000];
int n,t;
int left[1000],right[1000],col[1000];
char grid[1000][1000],grid1[1000][1000];
int d[1000][1000],d1[1000][1000];
queue<node>q;

void bfs(node s);
void bfst(node s);
int match(int n);
bool dfs(int s);

