            if(isdigit(grid1[i][j])){
                k=grid1[i][j]-'0';
                if(k>0)caps[i][j].fl=1;
                caps[i][j].ind=k;
                for(l=1;l<=k;l++){
                    caps[i][j].no[l]=mark++;
                }
            }
        }
    }
    mark=1;



    for(i=0;i<n;i++){
        for(j=0;j<n;j++){
            if(isdigit(grid[i][j])){
                k=grid[i][j]-'0';
                for(l=1;l<=k;l++){
                    temp.i=i; temp.j=j; temp.no=mark++;
                    bfst(temp);
                }
            }
        }
    }

