//          printf("%d ",v[i][j]);
//      }
//      printf("\n");
//  }

    printf("%d\n",match(mark-1));



    return 0;
}

bool dfs(int s){

    if(col[s]) return 0;
    int i,j,k,l;
    col[s]=1;

    for(i=0;i<v[s].size();i++){
        k=v[s][i];
        if(left[k]==-1){
            left[k]=s;
            right[s]=i;
            return true;
        }
        else if(dfs(left[k])){
            left[k]=s;
            right[s]=i;
            return true;
        }
    }

    return false;

}


int match(int n){

    memset(left,-1,sizeof(left));
    memset(right,-1,sizeof(right));
    int i,j,k,l,done;

    do{

        done=1;
        memset(col,0,sizeof(col));

        for(i=1;i<=n;i++){
            if(right[i]==-1&&dfs(i)) done=0;
        }



    }while(!done);

    k=0;

    for(i=1;i<=n;i++){
        if(right[i]!=-1) k++;

    }

    return k;

}

